/bin/sh -lc "python - <<'PY'
mods=['transformers','torch','nltk','wordfreq','sentencepiece','sklearn','ortools']
for m in mods:
 try:
  x=__import__(m); print(m,'yes',getattr(x,'__version__',''))
 except Exception as e: print(m,'no')
PY
find /usr/share -maxdepth 3 -type f \\( -iname '*words*' -o -iname '*.arpa' -o -iname '*corpus*' \\) 2>/dev/null | head -30"

